<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { NAlert, NButton, NForm, NSpin, NTabPane, NTabs, NTag } from 'naive-ui';
import type { BoardSnapshot, CallRecord, ProjectSnapshot, ProviderSummary, Reservation, ReviewRecord, Shot, ShotFields } from '../types.ts';
import { shotProblems, storyboardProblems } from '../lib/storyboard.ts';
import { formatDuration } from '../lib/timeline.ts';
import AppIcon from '../components/AppIcon.vue';
import type { HumanReviewInput } from '../lib/generationApi.ts';
import EmptyState from '../components/EmptyState.vue';
import ShotFieldsForm from '../components/ShotFieldsForm.vue';
import ShotCandidates from '../components/ShotCandidates.vue';
import DraftReview from '../components/DraftReview.vue';
import CallHistory from '../components/CallHistory.vue';

const props = defineProps<{ snapshot: ProjectSnapshot; board: BoardSnapshot | null; shots: Shot[]; selectedShot: Shot | null; selectedId: string | null; fields: ShotFields; editorMode: 'empty' | 'new' | 'existing'; editorDirty: boolean; editorConflict: boolean; editorBaseRevision: number; disabled: boolean; loading: boolean; error: string; calls: CallRecord[]; providers: ProviderSummary[]; reviewRevision: number; reviews: ReviewRecord[] }>();
const emit = defineEmits<{ 'update:fields': [fields: ShotFields]; create: []; select: [id: string]; save: []; archive: [id: string]; move: [input: { id: string; direction: -1 | 1 }]; addCandidate: [id: string]; selectCandidate: [id: string]; assets: []; timeline: []; refresh: []; reloadEditor: []; createDraft: []; applyDraft: [input: { id: string; acceptedOperationIds: string[] }]; renewDraft: [id: string]; reasoning: []; generate: [id: string]; review: [input: { shotId: string; review: HumanReviewInput }]; details: []; settle: [input: { id: string; actualAmount: number; currency: Reservation['currency']; note: string }] }>();
const tab = ref('board');
const issues = computed(() => storyboardProblems(props.shots, props.snapshot.artifacts));
const fieldIssues = computed(() => shotProblems(props.fields));
const selectedCount = computed(() => props.shots.filter(shot => Boolean(shot.selectedArtifactId)).length);
const oldCount = computed(() => props.shots.filter(shot => shot.selectedArtifactId && shot.selectedVisualRevision !== shot.visualRevision).length);
const pendingCount = computed(() => props.board?.drafts.filter(draft => draft.status === 'pending').length || 0);
watch(() => props.reviewRevision, () => { tab.value = 'review'; });
</script>

<template>
  <div class="storyboard-view"><header class="page-heading"><div><p class="eyebrow">ONE FRAME AT A TIME</p><h1>让故事有了画面</h1><p class="subheading">{{ snapshot.project.name }} · {{ shots.length }} 镜 · {{ formatDuration(shots.reduce((sum, shot) => sum + shot.durationMs, 0)) }}</p></div><div class="heading-actions"><NButton :disabled="disabled" @click="emit('details')">创作简报</NButton><NButton :disabled="disabled || !board || editorDirty" @click="emit('reasoning')">让模型提出草稿</NButton><NButton type="primary" :disabled="disabled || !board || editorDirty || issues.length > 0" @click="emit('timeline')"><template #icon><AppIcon name="workbench" :size="17" /></template>保存到时间线</NButton></div></header><NAlert v-if="error" type="error" :show-icon="false" class="inline-alert"><div class="alert-line"><span>{{ error }}</span><NButton :disabled="disabled" @click="emit('refresh')">重新载入</NButton></div></NAlert><div v-if="loading && !board" class="board-loading"><NSpin /><span>正在载入分镜…</span></div><template v-else-if="board"><div class="board-status-line"><span>分镜 r{{ board.revision }} · {{ selectedCount }} / {{ shots.length }} 镜已选素材</span><span v-if="oldCount" class="old-candidate-note">{{ oldCount }} 镜仍选用旧视觉要求的素材，请复核</span><span v-else-if="issues.length && shots.length" class="muted">{{ issues[0] }}</span><span v-else-if="shots.length" class="ready-note">镜头与素材已准备就绪</span></div><p class="form-note">保存到时间线会重建镜头与镜头字幕，保留最近已保存时间线的独立音轨与输出设置；新时长放不下原音轨时会明确报错。</p><NTabs v-model:value="tab" type="line" animated class="storyboard-tabs"><NTabPane name="board" tab="分镜工作台"><div class="storyboard-layout"><section class="panel shot-list-panel"><div class="panel-heading"><h2>镜头列表</h2><NButton quaternary size="small" :disabled="disabled" aria-label="新建镜头" @click="emit('create')"><AppIcon name="plus" :size="18" /></NButton></div><NButton dashed block :disabled="disabled" @click="emit('create')">添加镜头</NButton><p v-if="!shots.length" class="shot-list-empty">把故事拆成几个画面，<br />从第一镜开始。</p><div class="shot-list"><article v-for="(shot, index) in shots" :key="shot.id" class="shot-list-item" :class="{ selected: selectedId === shot.id }"><button class="shot-item-select" :aria-pressed="selectedId === shot.id" @click="emit('select', shot.id)"><span class="shot-order">{{ String(index + 1).padStart(2, '0') }}</span><div><strong>{{ shot.title }}</strong><p>{{ formatDuration(shot.durationMs) }} · {{ shot.selectedArtifactId ? shot.selectedVisualRevision === shot.visualRevision ? '已选素材' : '旧要求素材' : '待选素材' }}</p></div><span class="shot-dot" :class="{ ready: shot.selectedArtifactId && shot.selectedVisualRevision === shot.visualRevision, old: shot.selectedArtifactId && shot.selectedVisualRevision !== shot.visualRevision }"></span></button><div class="shot-order-actions"><NButton text size="tiny" :disabled="disabled || editorDirty || index === 0" :aria-label="`向前移动镜头 ${index + 1}`" @click="emit('move', { id: shot.id, direction: -1 })"><AppIcon name="up" :size="14" /></NButton><NButton text size="tiny" :disabled="disabled || editorDirty || index === shots.length - 1" :aria-label="`向后移动镜头 ${index + 1}`" @click="emit('move', { id: shot.id, direction: 1 })"><AppIcon name="down" :size="14" /></NButton></div></article></div><p class="panel-footnote">按列表顺序组成时间线。修改镜头不会删除历史候选。</p></section><section v-if="editorMode !== 'empty'" class="panel shot-editor-panel"><div class="panel-heading"><div class="heading-line"><h2>{{ editorMode === 'new' ? '新镜头' : '镜头内容' }}</h2><NTag size="small" :bordered="false" :type="editorDirty ? 'warning' : 'default'">{{ editorDirty ? '未保存' : editorMode === 'existing' ? `r${editorBaseRevision}` : '待创建' }}</NTag></div><NButton v-if="selectedShot && editorMode === 'existing'" text size="small" :disabled="disabled" @click="emit('archive', selectedShot.id)">归档镜头</NButton></div><NAlert v-if="editorConflict" type="warning" :show-icon="false" class="draft-alert">镜头在其他操作中已有更新。当前输入仍保留；请核对后重新载入最新版本。<NButton text type="primary" :disabled="disabled" @click="emit('reloadEditor')">重新载入</NButton></NAlert><NForm @submit.prevent="emit('save')"><ShotFieldsForm :model-value="fields" :artifacts="snapshot.artifacts" :disabled="disabled" @update:model-value="emit('update:fields', $event)" /><div class="shot-editor-footer"><span class="muted small">{{ fieldIssues[0] || '改动画面要求会建立新的视觉修订。' }}</span><NButton type="primary" attr-type="submit" :disabled="disabled || fieldIssues.length > 0 || editorConflict || (editorMode === 'existing' && !editorDirty)">{{ editorMode === 'new' ? '创建镜头' : '保存镜头' }}</NButton></div></NForm></section><EmptyState v-else title="每一镜，都有它的理由" description="先写镜头，再选画面。无需模型连接，也能一步步完成自己的作品。" icon="storyboard"><NButton type="primary" :disabled="disabled" @click="emit('create')">创建第一镜</NButton></EmptyState><div v-if="selectedShot && editorMode === 'existing'" class="shot-candidate-column"><NAlert v-if="editorDirty" type="info" :show-icon="false" class="candidate-edit-notice">先保存镜头修改，再添加或选择候选。</NAlert><ShotCandidates :shot="selectedShot" :candidates="board.candidates" :artifacts="snapshot.artifacts" :reviews="reviews" :disabled="disabled || editorDirty" @add="emit('addCandidate', $event)" @select="emit('selectCandidate', $event)" @assets="emit('assets')" @generate="emit('generate', selectedShot.id)" @review="emit('review', { shotId: selectedShot.id, review: $event })" /></div><div v-else-if="editorMode === 'new'" class="panel new-shot-guide"><AppIcon name="image" :size="34" /><h3>先留下这一镜的想法</h3><p>保存镜头后，可以从素材库加入多个候选，再选出最适合故事的一版。</p></div></div></NTabPane><NTabPane name="review" :tab="`草稿与调用${pendingCount ? ` · ${pendingCount}` : ''}`"><div class="review-layout"><DraftReview :board="board" :disabled="disabled" :editor-dirty="editorDirty" @apply="emit('applyDraft', $event)" @renew="emit('renewDraft', $event)" @create="emit('createDraft')" /><CallHistory :calls="calls" :providers="providers" :disabled="disabled" @refresh="emit('refresh')" @settle="emit('settle', $event)" /></div></NTabPane></NTabs></template></div>
</template>
